import ipaddress,json,os,pathlib,re,struct,sys,tempfile
def build(request):
    if not isinstance(request,dict) or set(request)!={'vlan','source_mac','source_ip','target_ip'}:raise ValueError('fields')
    vid=request['vlan'];mac=request['source_mac']
    if type(vid)is not int or not 1<=vid<=4094:raise ValueError('VID')
    if not isinstance(mac,str) or not re.fullmatch(r'(?:[0-9A-Fa-f]{2}:){5}[0-9A-Fa-f]{2}',mac):raise ValueError('MAC')
    source=bytes.fromhex(mac.replace(':',''))
    if source[0]&1 or not any(source):raise ValueError('unicast nonzero source MAC')
    addresses=[]
    for name in ('source_ip','target_ip'):
        if not isinstance(request[name],str):raise ValueError('IPv4 text required')
        address=ipaddress.IPv4Address(request[name])
        if address.is_multicast or address.is_unspecified or address==ipaddress.IPv4Address('255.255.255.255'):raise ValueError('unicast IPv4 required')
        addresses.append(address.packed)
    if addresses[0]==addresses[1]:raise ValueError('ordinary request, not gratuitous ARP')
    arp=struct.pack('!HHBBH',1,0x0800,6,4,1)+source+addresses[0]+b'\x00'*6+addresses[1]
    frame=b'\xff'*6+source+struct.pack('!HH',0x8100,vid)+struct.pack('!H',0x0806)+arp
    frame=frame.ljust(60,b'\x00') # Minimum Ethernet frame excluding FCS.
    return struct.pack('<IHHIIII',0xa1b2c3d4,2,4,0,0,65535,1)+struct.pack('<IIII',1,0,len(frame),len(frame))+frame
def main():
    try:
        data=build(json.loads(pathlib.Path(sys.argv[1]).read_text()))
    except (ValueError,TypeError,KeyError,IndexError,OSError):return 2
    fd,tmp=tempfile.mkstemp(prefix='.capture-',dir='.')
    try:
        with os.fdopen(fd,'wb') as out:out.write(data)
        os.replace(tmp,'request.pcap')
    finally:
        if os.path.exists(tmp):os.unlink(tmp)
    return 0
if __name__=='__main__':raise SystemExit(main())
```

标记位于源MAC后、内层EtherType前；ARP请求的以太网目的为广播，而请求体中的目标硬件地址为未知的全零。VID并不替代IP，ARP请求本身不会跨路由器转发。

原题原理说明：
典型二层交换依据MAC地址和VLAN内学习的转发表转发以太帧，未知单播及广播的处理受该广播域约束；路由依据目的IP与路由表在不同IP网络间选择下一跳。VLAN把二层网络分成独立广播域，跨VLAN通信通常需要三层接口及路由策略。三层交换机可同时承担这些功能，因此应按功能而不是设备名称判断路径；VLAN本身不自动提供加密。

